        id: 'licensing',
        title: 'Licensing: open source versus source-available',
        content: '**Three of these four are OSI-approved open source under MIT; n8n is not, and that distinction can matter more than any feature.** LangGraph, CrewAI and Microsoft Agent Framework are all MIT-licensed, which means you can use, modify and redistribute them commercially with essentially no restriction beyond attribution.\n\nn8n uses the Sustainable Use License. The Community Edition is free and the source is available, but the licence restricts reselling n8n itself, which is a real constraint if you intend to build a product whose core value is a hosted n8n. This is not a criticism of the licence — it is a deliberate and reasonable business model — but it is a legal question you should answer before architecture, not after. Read the licence text rather than the marketing page.\n\nThe AG2 fork is Apache-2.0, which is also OSI-approved but includes an explicit patent grant that MIT lacks. For most teams this makes no practical difference; for legal review at a large company it sometimes does.',
