      regionalContext: {
        id: 'regional-context',
        title: 'Agent frameworks in the EU, Japan and China',
        content: 'An agent framework decides where your prompts, tool outputs and intermediate reasoning go. That makes the hosted-versus-self-hosted question a compliance question in three major markets, not just an operations preference.',
        subsections: [
          {
            title: 'European Union',
            content: 'Agent workflows tend to touch more personal data than a single prompt does, because tool calls pull in CRM records, tickets and documents as the run proceeds. Under the GDPR that whole trace is processing, and a hosted tracing service that stores it constitutes a transfer if the service runs outside the EU. You need an Article 28 processor agreement with whichever managed layer you adopt — LangSmith or n8n Cloud in practice. The EU AI Act adds a second consideration for agents that act rather than advise: the Digital Omnibus deferred the Annex III high-risk obligations to 2 December 2027, but transparency duties arrive earlier, and an agent taking consequential actions is exactly the kind of system those rules target. Self-hosting all four is possible and keeps the trace inside your perimeter.',
          },
          {
            title: 'Japan',
            content: 'METI\'s AI governance work pushes Japanese firms towards auditable data paths, and agent systems are where auditability is hardest, since the interesting behaviour is emergent across many steps. This is a concrete argument for LangGraph\'s explicit state graph over a conversational pattern: a graph you can serialise and replay is an audit artefact, whereas a free-form agent conversation is a transcript you have to interpret. If you are also running the models domestically, checkpointing gives you a record of exactly which state produced which action.',
          },
          {
            title: 'China',
            content: 'Under the Data Security Law (数据安全法) and the CAC\'s cross-border rules, the exposure in an agent system is broader than in a single inference call, because tool outputs and intermediate state also leave the country if the orchestration is hosted abroad. Deployments serving mainland teams generally need both the models and the orchestration running on domestic infrastructure. All four frameworks can be self-hosted, which makes the framework choice less of a constraint here than the model choice — see [running local LLMs in China](/local-llms/deepseek-local-china-data-privacy-2026).',
          },
        ],
        note: 'Self-host the orchestration in any market where the full execution trace, not just the prompt, has to stay inside your jurisdiction. All four support it.',
      },
