        title: 'Was ein Agenten-Framework tatsächlich leistet',
        content: '**Ein Framework zur Agenten-Orchestrierung verwaltet Kontrollfluss, Zustand und Koordination zwischen mehreren LLM-Aufrufen, damit Sie Schleife, Wiederholungen und Nachrichtenaustausch nicht selbst schreiben müssen.** Es regelt, welcher Agent als Nächstes läuft, was jeder sehen darf, was bei einem Fehlschlag geschieht und wie ein langlaufender Auftrag nach einer Pause fortgesetzt wird.\n\nDas ist wirklich nützlich, sobald Sie mehrere Agenten, verzweigte Logik oder Zustand haben, der einen Neustart überdauern muss. Es ist Overhead, wenn ein Agent einen Werkzeugaufruf macht — weshalb der häufigste Fehler in dieser Kategorie darin besteht, ein Framework einzuführen, bevor das Problem eines verlangt.',
