      licensing: {
        id: 'licensing',
        title: 'Lizenzen: Open Source oder quelloffen einsehbar',
        content: '**Drei der vier sind von der OSI anerkanntes Open Source unter MIT; n8n ist es nicht, und diese Unterscheidung kann wichtiger sein als jede Funktion.** LangGraph, CrewAI und Microsoft Agent Framework sind alle MIT-lizenziert, was bedeutet, dass Sie sie kommerziell nutzen, verändern und weitergeben dürfen, im Wesentlichen ohne Einschränkung über die Namensnennung hinaus.\n\nn8n nutzt die Sustainable Use License. Die Community Edition ist kostenlos und der Quelltext einsehbar, doch die Lizenz beschränkt den Weiterverkauf von n8n selbst, was eine echte Einschränkung ist, wenn Sie ein Produkt bauen wollen, dessen Kernwert ein gehostetes n8n ist. Das ist keine Kritik an der Lizenz — es ist ein bewusstes und vernünftiges Geschäftsmodell —, aber es ist eine Rechtsfrage, die Sie vor der Architektur klären sollten, nicht danach. Lesen Sie den Lizenztext statt der Marketingseite.\n\nDer AG2-Fork steht unter Apache-2.0, ebenfalls von der OSI anerkannt, enthält aber eine ausdrückliche Patentgewährung, die MIT fehlt. Für die meisten Teams macht das praktisch keinen Unterschied; für die Rechtsprüfung in einem großen Konzern manchmal schon.',
        note: 'Prüfen Sie die Lizenz, bevor Sie ein kommerzielles Produkt auf eines dieser Werkzeuge aufbauen. MIT und Apache-2.0 lassen Ihnen freie Hand; die Sustainable Use License enthält eine Weiterverkaufsbeschränkung, die Einkauf oder Rechtsabteilung sehen wollen.',
      },
      whoShouldUse: {
        id: 'who-should-use',
        title: 'Wer sollte was nutzen?',
        content: '**Ihre Kontrollanforderungen und die Frage, wer den Workflow schreibt, entscheiden.** Fünf Profile decken die meisten Leserinnen und Leser ab.',
        items: [
          '**Backend- oder ML-Engineer mit einem regulierten, langlaufenden Agenten** → LangGraph, wegen Checkpointing, Fortsetzbarkeit und prüfbarem Kontrollfluss.',
          '**Wer bis Ende der Woche eine Demo braucht** → CrewAI, und später zu LangGraph wechseln, falls die Verzweigungen dem Rollenmodell entwachsen.',
          '**Ein .NET- oder Azure-Haus** → Microsoft Agent Framework. Es ist hier die einzige Option mit erstklassiger .NET-Unterstützung, und Microsoft hat es als Nachfolger von AutoGen bestimmt.',
          '**Ein Operations-, RevOps- oder Growth-Team** → n8n, wo der Agent ein Knoten unter Ihren bestehenden Integrationen ist und Nicht-Entwickler ihn pflegen können.',
          '**Ein Team, das Modelle auf eigener Hardware betreibt** → LangGraph oder CrewAI gegen einen lokalen Endpunkt, da beide keinen gehosteten Dienst voraussetzen. Siehe [lokale gegen Cloud-Agenten](/de/local-llms/local-vs-cloud-agents).',
        ],
      },
      regionalContext: {
        id: 'regional-context',
        title: 'Agenten-Frameworks in der EU, in Japan und in China',
        content: 'Ein Agenten-Framework entscheidet, wohin Ihre Prompts, Werkzeugausgaben und Zwischenschritte gehen. Damit wird die Frage nach gehostet oder selbst betrieben in drei wichtigen Märkten zur Compliance-Frage und nicht nur zur Betriebspräferenz.',
        subsections: [
          {
            title: 'Europäische Union',
            content: 'Agenten-Workflows berühren tendenziell mehr personenbezogene Daten als ein einzelner Prompt, weil Werkzeugaufrufe im Verlauf CRM-Datensätze, Tickets und Dokumente hereinziehen. Nach der DSGVO ist dieser gesamte Ablauf eine Verarbeitung, und ein gehosteter Tracing-Dienst, der ihn speichert, stellt eine Übermittlung dar, wenn er außerhalb der EU läuft. Sie brauchen einen Auftragsverarbeitungsvertrag nach Artikel 28 mit der verwalteten Ebene, für die Sie sich entscheiden — in der Praxis LangSmith oder n8n Cloud. Der EU AI Act bringt eine zweite Überlegung für Agenten, die handeln statt beraten: Der Digital Omnibus hat die Hochrisiko-Pflichten aus Anhang III auf den 2. Dezember 2027 verschoben, doch Transparenzpflichten greifen früher, und ein Agent, der folgenreiche Handlungen ausführt, ist genau die Art System, auf die diese Regeln zielen. Alle vier lassen sich selbst hosten, wodurch der Ablauf in Ihrem Perimeter bleibt.',
          },
          {
            title: 'Japan',
            content: 'Die AI-Governance-Arbeit des METI drängt japanische Unternehmen zu auditierbaren Datenwegen, und bei Agentensystemen ist Auditierbarkeit am schwersten, da das interessante Verhalten über viele Schritte hinweg entsteht. Das ist ein konkretes Argument für LangGraphs expliziten Zustandsgraphen gegenüber einem Konversationsmuster: Ein Graph, den Sie serialisieren und erneut abspielen können, ist ein Prüfartefakt, während ein freies Agentengespräch ein Protokoll ist, das Sie interpretieren müssen. Wenn Sie die Modelle zusätzlich im Inland betreiben, liefert Checkpointing einen Nachweis darüber, welcher Zustand genau welche Handlung erzeugt hat.',
          },
          {
            title: 'China',
            content: 'Unter dem Datensicherheitsgesetz (数据安全法) und den CAC-Regeln zur grenzüberschreitenden Übermittlung ist das Risiko in einem Agentensystem breiter als bei einem einzelnen Inferenzaufruf, weil auch Werkzeugausgaben und Zwischenzustände das Land verlassen, wenn die Orchestrierung im Ausland gehostet wird. Bereitstellungen für Teams auf dem Festland verlangen in der Regel, dass sowohl die Modelle als auch die Orchestrierung auf inländischer Infrastruktur laufen. Alle vier Frameworks lassen sich selbst hosten, wodurch die Framework-Wahl hier weniger einschränkend ist als die Modellwahl — siehe [lokale LLMs in China betreiben](/de/local-llms/deepseek-local-china-data-privacy-2026).',
          },
        ],
        note: 'Hosten Sie die Orchestrierung in jedem Markt selbst, in dem der vollständige Ausführungsverlauf und nicht nur der Prompt in Ihrer Rechtsordnung bleiben muss. Alle vier unterstützen das.',
      },
