            verdict: 'n8n coloca un nodo de agente de IA en un lienzo visual junto a nodos de CRM, Slack, correo y bases de datos, que es exactamente lo correcto cuando el agente es un paso de un flujo operativo y no el sistema entero. Sus 202,7k estrellas son con diferencia la cifra más alta de esta página, pero miden su identidad como herramienta general de automatización más que su adopción específica como plataforma de agentes, así que no las lea como un veredicto sobre capacidad agéntica. Autoalojar la Community Edition es gratis. Cloud empieza en 20 euros al mes con facturación anual para 2.500 ejecuciones con usuarios ilimitados, luego 50 euros para Pro con 10.000 ejecuciones y 667 euros para Business con 40.000 ejecuciones y opción de autoalojamiento. La licencia merece atención: n8n usa la Sustainable Use License, que es de código disponible y no código abierto aprobado por la OSI, y restringe revender n8n en sí.',
