            type: 'tip',
            text: 'LangSmith y n8n Cloud miden el uso además de los puestos: trazas en un caso, ejecuciones en el otro. Estime su volumen mensual antes de comparar precios de portada, porque un plan de 20 euros con 2.500 ejecuciones y un puesto de 39 $ con 10.000 trazas no son unidades comparables.',
