          '**n8n** — 202,7k etoiles, mais sous la Sustainable Use License, a source disponible et non open source approuve par l\'OSI. Cloud demarre a 20 euros par mois en facturation annuelle pour 2 500 executions ; Business coute 667 euros.',
          '**Seul n8n dispose d\'un programme d\'affiliation verifiable :** 30 % des revenus nets sur les parrainages Cloud pendant 12 mois, verses mensuellement par PayPal au-dela de 100 euros de solde, la publicite payante etant expressement interdite. PromptQuorum n\'y est pas inscrit et ne gagne rien sur cette page.',
