        title: 'Ce que fait vraiment un framework d\'agents',
        content: '**Un framework d\'orchestration d\'agents gere le flux de controle, l\'etat et la coordination entre plusieurs appels au modele, pour que vous n\'ecriviez pas a la main la boucle, les reprises et l\'echange de messages.** Il decide quel agent s\'execute ensuite, ce que chacun peut voir, ce qui se passe quand une etape echoue et comment un travail long reprend apres une pause.\n\nC\'est reellement utile des que vous avez plusieurs agents, une logique ramifiee ou un etat qui doit survivre a un redemarrage. C\'est du poids mort quand vous avez un agent effectuant un appel d\'outil — d\'ou l\'erreur la plus courante dans cette categorie : adopter un framework avant que le probleme n\'en reclame un.',
