        content: '**LangGraph est celui a choisir quand l\'agent doit etre inspectable, reprenable et correct, et pas seulement impressionnant en demo.** Il modelise le flux comme un graphe oriente explicite a etat partage : plus de travail au depart et nettement moins quand quelque chose deraille a trois heures du matin.',
