            verdict: 'LangGraph vient de l\'equipe LangChain et est oriente code en Python et JavaScript. Vous definissez des noeuds, des aretes et un objet d\'etat partage, ce qui rend le flux de controle lisible plutot que deductible du texte des invites. Les benefices concrets sont les points de reprise, qui permettent a un travail long de repartir la ou il s\'est arrete, et les primitives d\'interruption integrees pour l\'approbation humaine — precisement les deux fonctions que les equipes finissent le plus souvent par mal reconstruire a la main. La bibliotheque est MIT et gratuite a auto-heberger indefiniment. La couche commerciale, ce sont LangSmith et la plateforme de deploiement : une offre Developer a 0 $ par siege avec jusqu\'a 5 000 traces de base par mois, Plus a 39 $ par siege et par mois avec jusqu\'a 10 000 traces de base et un petit deploiement serverless gratuit, et des tarifs Enterprise sur devis avec options auto-hebergee et hybride. Le calcul et le stockage au-dela du quota sont factures a part, a 1,50 $ le LCU et 1,00 $ le LSU.',
