            verdict: 'CrewAI est le plus etoile des frameworks orientes code presentes ici, avec 57,7k, et le modele par roles en est la raison. Definir un Agent avec un role et un objectif, une Task avec une sortie attendue et une Crew avec un processus met en route un pipeline multi-agents avec bien moins de code qu\'un graphe d\'etat equivalent. Cette lisibilite est un vrai atout en equipe : un nouvel arrivant comprend un script CrewAI plus vite qu\'un script LangGraph. La contrepartie est la granularite : des que votre flux exige des ramifications reellement complexes, des reprises conditionnelles ou un controle precis de ce que voit chaque agent a chaque etape, vous travaillerez contre l\'abstraction plutot qu\'avec elle. La bibliotheque est MIT et gratuite. L\'offre hebergee Basic est gratuite avec 50 executions de flux par mois et inclut un editeur visuel et l\'integration GitHub ; au-dela, seul Enterprise existe, sans montant publie.',
