      regionalContext: {
        id: 'regional-context',
        title: 'Les frameworks d\'agents dans l\'UE, au Japon et en Chine',
        content: 'Un framework d\'agents decide ou partent vos invites, les sorties d\'outils et le raisonnement intermediaire. La question de l\'heberge contre l\'auto-heberge devient donc une question de conformite sur trois marches majeurs, et non une simple preference d\'exploitation.',
        subsections: [
          {
            title: 'Union europeenne',
            content: 'Les flux d\'agents touchent generalement plus de donnees personnelles qu\'une invite isolee, car les appels d\'outils font entrer des fiches CRM, des tickets et des documents au fil de l\'execution. Au sens du RGPD, l\'ensemble de cette trace constitue un traitement, et un service de tracage heberge qui la conserve constitue un transfert s\'il opere hors de l\'UE. Il vous faut un contrat de sous-traitance au titre de l\'article 28 avec la couche geree que vous adoptez — LangSmith ou n8n Cloud en pratique. Le reglement europeen sur l\'IA ajoute une seconde consideration pour les agents qui agissent plutot qu\'ils ne conseillent : le Digital Omnibus a reporte les obligations a haut risque de l\'annexe III au 2 decembre 2027, mais les devoirs de transparence arrivent plus tot, et un agent executant des actions consequentes est exactement le type de systeme que ces regles visent. Les quatre peuvent etre auto-heberges, ce qui maintient la trace dans votre perimetre.',
          },
          {
            title: 'Japon',
            content: 'Les travaux de gouvernance de l\'IA du METI poussent les entreprises japonaises vers des chemins de donnees auditables, et c\'est dans les systemes d\'agents que l\'auditabilite est la plus difficile, puisque le comportement interessant emerge au fil de nombreuses etapes. C\'est un argument concret en faveur du graphe d\'etat explicite de LangGraph face a un motif conversationnel : un graphe que l\'on peut serialiser et rejouer est un artefact d\'audit, tandis qu\'une conversation libre entre agents est une transcription qu\'il faut interpreter. Si vous faites en outre tourner les modeles sur le territoire, les points de reprise vous donnent la trace de l\'etat exact ayant produit chaque action.',
          },
          {
            title: 'Chine',
            content: 'Sous la loi sur la securite des donnees (数据安全法) et les regles de la CAC sur les transferts transfrontaliers, l\'exposition dans un systeme d\'agents est plus large que pour un simple appel d\'inference, car les sorties d\'outils et l\'etat intermediaire quittent eux aussi le pays si l\'orchestration est hebergee a l\'etranger. Les deploiements servant des equipes de Chine continentale exigent generalement que les modeles comme l\'orchestration tournent sur une infrastructure domestique. Les quatre frameworks peuvent etre auto-heberges, ce qui rend ici le choix du framework moins contraignant que celui du modele — voir [executer des LLM locaux en Chine](/fr/local-llms/deepseek-local-china-data-privacy-2026).',
          },
        ],
        note: 'Auto-hebergez l\'orchestration sur tout marche ou la trace complete d\'execution, et pas seulement l\'invite, doit rester dans votre juridiction. Les quatre le permettent.',
      },
