          '**So o n8n tem programa de afiliados verificavel:** 30% da receita liquida em indicacoes do Cloud por 12 meses, pago mensalmente via PayPal acima de 100 euros de saldo, com publicidade paga expressamente proibida. A PromptQuorum nao esta inscrita e nao ganha nada com esta pagina.',
