        content: '**Um framework de orquestracao de agentes gerencia o fluxo de controle, o estado e a coordenacao entre varias chamadas ao modelo, para que voce nao precise escrever a mao o laco, as retentativas e a troca de mensagens.** Ele decide qual agente executa em seguida, o que cada um pode ver, o que acontece quando uma etapa falha e como um trabalho longo e retomado apos uma pausa.\n\nIsso e realmente util assim que voce tem varios agentes, logica ramificada ou estado que precisa sobreviver a um reinicio. E peso morto quando voce tem um agente fazendo uma chamada de ferramenta — por isso o erro mais comum nesta categoria e adotar um framework antes de o problema exigir um.',
