        note: 'Orce a camada gerenciada separadamente dos tokens do modelo. Para a maioria das equipes a conta de tokens e o maior custo recorrente, e rotea-la bem importa mais — veja [o melhor gateway de API para LLM](/pt/local-llms/best-llm-api-gateway-2026).',
