            whyItMatters: 'O AutoGen esta em modo manutencao e o proprio README orienta novos usuarios a comecar pelo Microsoft Agent Framework. Conselhos em sentido contrario sao anteriores a mudanca e hoje enviam equipes a um projeto que nao recebera novos recursos.',
