        title: 'AutoGen 与 AG2 后来怎么了',
        content: '**不要在 AutoGen 上启动新工作，并且要警惕任何仍在推荐它的指南。** `microsoft/autogen` 仓库挂着维护模式横幅，声明 AutoGen「不会再获得新功能或增强，今后由社区管理」，并引导新用户前往 Microsoft Agent Framework。微软为既有用户发布了正式的迁移指南。\n\n该仓库仍显示 6.07 万星标，而这个数字正是一处广泛误传的源头。多篇对比文章把大约 6 万星标归给社区分支 **AG2**，并将其描绘成蓬勃发展的延续。事实上 AG2 只有 4.9 千星标，许可证是 Apache-2.0 而非 MIT。它确实活跃——我们核实的当天它就有更新，未决问题也远少于原仓库——但规模远小于那些文章所暗示的。\n\n还有一处值得了解的许可细节：AutoGen 仓库附带两个许可文件。`LICENSE-CODE` 是 MIT，覆盖代码；而 `LICENSE` 是知识共享署名 4.0，覆盖非代码内容。仓库元数据报告的是知识共享那一份，这也是某些表格把 AutoGen 标为内容许可证的原因。',
