        content: '**에이전트 오케스트레이션 프레임워크는 여러 번의 모델 호출에 걸친 제어 흐름과 상태, 조율을 관리해, 루프와 재시도와 메시지 전달을 직접 작성하지 않아도 되게 해줍니다.** 다음에 어떤 에이전트가 실행될지, 각자가 무엇을 볼 수 있는지, 한 단계가 실패하면 어떻게 되는지, 오래 걸리는 작업이 중단 후 어떻게 재개되는지를 처리합니다.\n\n에이전트가 여럿이거나, 분기 로직이 있거나, 재시작을 넘어 살아남아야 하는 상태가 있다면 이는 정말 유용합니다. 반면 에이전트 하나가 도구를 한 번 호출하는 정도라면 부담일 뿐입니다. 이 분야에서 가장 흔한 실수가 문제가 아직 요구하지 않는데도 프레임워크를 도입하는 것인 이유입니다.',
